package br.com.sussmartcare.clinicalquery.infrastructure; import br.com.sussmartcare.clinicalquery.application.ClinicalPatientViewSnapshot; import com.fasterxml.jackson.databind.ObjectMapper; import java.time.*; import java.util.*; import org.slf4j.*; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Component;
@Component public class ClinicalPatientViewCache {private static final Logger log=LoggerFactory.getLogger(ClinicalPatientViewCache.class);private final StringRedisTemplate redis;private final ObjectMapper mapper;public ClinicalPatientViewCache(StringRedisTemplate r,ObjectMapper m){redis=r;mapper=m;}private String key(UUID id){return "clinical-view:"+id;}public void put(ClinicalPatientViewSnapshot v){try{redis.opsForValue().set(key(v.visitId()),mapper.writeValueAsString(v),Duration.ofMinutes(10));}catch(Exception e){log.warn("clinical_view_cache_write_failed visit={}",v.visitId());}}public Optional<ClinicalPatientViewSnapshot> get(UUID id){try{String json=redis.opsForValue().get(key(id));return json==null?Optional.empty():Optional.of(mapper.readValue(json,ClinicalPatientViewSnapshot.class));}catch(Exception e){log.warn("clinical_view_cache_read_failed visit={}",id);return Optional.empty();}}}
